// droidMessage builds a Droid JSONL line with the given type, id, and optional usage.
func droidMessage(typ, id, role string, usage map[string]int) string {
	inner := map[string]interface{}{
		"role":    role,
		"content": []interface{}{},
	}
	if usage != nil {
		inner["id"] = id
		inner["usage"] = usage
	}
	msg, _ := json.Marshal(inner)
	line := map[string]interface{}{
		"type":    typ,
		"id":      id,
		"message": json.RawMessage(msg),
	}
	b, _ := json.Marshal(line)
	return string(b)
}

